      "characters": ["map_reader", "scout", "magic_helper", "bridge_crosser"]
    },
    {
      "scene_number": 2,
      "caption": "Frightened townspeople whisper from a side alley.",
      "visual_description": "Huddled figures in ragged cloaks point toward the inner city, their faces lit by a distant torch.",
      "characters": ["scout", "townspeaker"]
    },
    {
      "scene_number": 3,
      "caption": "Armored patrols march past a broken market stall.",
      "visual_description": "Three soldiers in dented plate armor carry spears under a faded arch, their shadows long in the dusk.",
      "characters": ["scout", "bridge_crosser"]
    },
    {
      "scene_number": 4,
      "caption": "The team slips through a hidden passage beneath the old plaza.",
      "visual_description": "Cobweb-draped stone steps descend into darkness, lit only by a small brass compass held in a gloved hand.",
      "characters": ["map_reader", "scout", "magic_helper", "bridge_crosser"]
    },
    {
      "scene_number": 5,
      "caption": "A cursed tower looms beyond a cracked courtyard.",
      "visual_description": "A spiral tower with glowing blue windows stands at the courtyard's end, surrounded by scattered rubble and a lone wilted banner.",
      "characters": ["magic_helper", "map_reader"]
    },
    {
      "scene_number": 6,
      "caption": "The team enters the tower's cold blue ground floor.",
      "visual_description": "Frost coats the stone walls and a heavy iron door stands ajar, blue light spilling from a stairwell above.",
      "characters": ["scout", "magic_helper", "bridge_crosser"]
    },
    {
      "scene_number": 7,
      "caption": "A magic door blocks the upper stair with shifting symbols.",
      "visual_description": "A stone door carved with moving runes pulses with amber light; the magic helper raises a crystal key toward it.",
      "characters": ["magic_helper", "map_reader"]
    },
    {
      "scene_number": 8,
      "caption": "The key unlocks the door, revealing a mirror hall.",
      "visual_description": "The door swings open to a long hall of silver mirrors that reflect the team's images infinitely, warm lamp light flickering from sconces.",
      "characters": ["map_reader", "scout", "magic_helper", "bridge_crosser"]
    },
    {
      "scene_number": 9,
      "caption": "A false reflection traps the scout in a mirror.",
      "visual_description": "The scout reaches toward a mirror that shows a different face; the image grabs his wrist while the others shout.",
      "characters": ["scout", "magic_helper", "bridge_crosser"]
    },
    {
      "scene_number": 10,
      "caption": "The magic helper breaks the illusion with a mirror shard.",
      "visual_description": "She holds a sharp mirror shard that glows white; the false reflection shatters and the scout falls free.",
      "characters": ["scout", "magic_helper", "bridge_crosser"]
    },
    {
      "scene_number": 11,
      "caption": "They find the rescue target in a high tower chamber.",
      "visual_description": "A small figure in a torn cloak sits on a stone floor beneath a high arched window, moonlight streaming through iron bars.",
      "characters": ["map_reader", "scout", "magic_helper", "bridge_crosser", "rescue_target"]
    },
    {
      "scene_number": 12,
      "caption": "Armored patrols storm the tower base below.",
      "visual_description": "Through a floor grate, torches and spear tips crowd the lower hall as soldiers shout orders.",
      "characters": ["scout", "bridge_crosser", "rescue_target"]
    },
    {
      "scene_number": 13,
      "caption": "The team hurries down a back stair to the old plaza.",
      "visual_description": "A narrow spiral stair with crumbling steps ends at a moonlit plaza littered with broken statues and old banners.",
      "characters": ["map_reader", "scout", "magic_helper", "bridge_crosser", "rescue_target"]
    },
    {
      "scene_number": 14,
      "caption": "Dragons are rumored above, but only a large bird passes.",
      "visual_description": "A vast shadow crosses the moon; the team ducks under a stone arch, but it is only a giant raven circling the tower.",
      "characters": ["bridge_crosser", "rescue_target"]
    },
    {
      "scene_number": 15,
      "caption": "They reach the bridge controls at the city's edge.",
      "visual_description": "A heavy lever mechanism stands on a stone platform beside a rope bridge over a deep ravine, dawn light just beginning to glow.",
      "characters": ["map_reader", "bridge_crosser"]
    },
    {
      "scene_number": 16,
      "caption": "The bridge lever is jammed; the scout works it free.",
      "visual_description": "The scout wrenches a rusted pin from the lever housing while the others watch the patrol torches approach.",
      "characters": ["scout", "map_reader", "magic_helper", "bridge_crosser", "rescue_target"]
    },
    {
      "scene_number": 17,
      "caption": "The team crosses the bridge as the patrols arrive.",
      "visual_description": "Figures hurry across the swaying rope bridge against a sunrise sky; soldiers stop at the near end, unable to follow.",
      "characters": ["map_reader", "scout", "magic_helper", "bridge_crosser", "rescue_target"]
    },
    {
      "scene_number": 18,
      "caption": "They cut the bridge and watch the ruined city fade.",
      "visual_description": "The rope bridge falls into the ravine as the team stands on safe ground, the sun rising over the distant towers and torn banners.",
      "characters": ["map_reader", "scout", "magic_helper", "bridge_crosser", "rescue_target"]
    }
  ]
}
```

